// biometric/biometric.types.ts

import { Types } from 'mongoose';

/**
 * Event Types generated by biometric access attempts
 */
export type BiometricEventType = 'CHECK_IN' | 'CHECK_OUT' | 'ACCESS' | 'UNKNOWN';

/**
 * Physical verification method used on the device
 */
export type BiometricVerificationType = 'FINGERPRINT' | 'FACE' | 'RFID' | 'CARD' | 'PIN' | 'UNKNOWN';

/**
 * Hardware modality type
 */
export type BiometricDeviceType = 'FINGERPRINT' | 'FACE' | 'RFID' | 'CARD' | 'MULTI_MODAL' | 'UNKNOWN';

/**
 * Network / Communication protocol category
 */
export type BiometricConnectionType = 'PUSH' | 'TCP_IP' | 'HTTP' | 'HTTPS' | 'SDK' | 'POLLING' | 'UNKNOWN';

/**
 * Device operational status
 */
export type BiometricDeviceStatus = 'ONLINE' | 'OFFLINE' | 'DISABLED' | 'UNKNOWN';

/**
 * Biometric User Mapping Status
 */
export type BiometricUserStatus = 'active' | 'suspended' | 'deleted';

/**
 * Event Processing & Access Validation Status Codes
 */
export type BiometricReasonCode =
  | 'ACCESS_ALLOWED'
  | 'DEVICE_NOT_FOUND'
  | 'DEVICE_DISABLED'
  | 'BIOMETRIC_USER_NOT_REGISTERED'
  | 'MEMBER_NOT_FOUND'
  | 'MEMBERSHIP_EXPIRED'
  | 'MEMBERSHIP_FROZEN'
  | 'MEMBERSHIP_INACTIVE'
  | 'MEMBERSHIP_NOT_STARTED'
  | 'NO_ACTIVE_MEMBERSHIP'
  | 'ACCESS_DISABLED'
  | 'DUPLICATE_EVENT'
  | 'INVALID_EVENT'
  | 'PROCESSING_FAILED';

/**
 * Event Log Processing Lifecycle State
 */
export type BiometricProcessingStatus =
  | 'RECEIVED'
  | 'PROCESSED'
  | 'DUPLICATE'
  | 'UNKNOWN_USER'
  | 'DEVICE_DISABLED'
  | 'MEMBERSHIP_DENIED'
  | 'PROCESSING_FAILED';

/**
 * Standardized, normalized event schema received by the core business service.
 * The core layer ONLY consumes this format.
 */
export interface NormalizedBiometricEvent {
  deviceId?: string;
  deviceSerialNumber?: string;
  biometricUserId: string;
  eventType: BiometricEventType;
  verificationType?: BiometricVerificationType;
  eventTime: Date | string;
  transactionId?: string | null;
  rawData?: Record<string, any>;
}

/**
 * Standard response output from BiometricService.processBiometricEvent
 */
export interface BiometricProcessingResult {
  success: boolean;
  accessAllowed: boolean;
  reason: BiometricReasonCode;
  message: string;
  deviceId?: string;
  memberId?: string;
  memberName?: string;
  attendanceId?: string;
  eventTime: Date;
  eventType: BiometricEventType;
  verificationType: BiometricVerificationType;
  transactionId?: string | null;
}

/**
 * Interface that all vendor-specific adapters must implement.
 */
export interface BiometricAdapter {
  adapterName: string;
  normalizeEvent(rawEvent: any): NormalizedBiometricEvent;
}
